package com.whaa.shop.customerService.application;
import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.customerService.domain.KnowledgeFile;import com.whaa.shop.customerService.infrastructure.KnowledgeFileMapper;import com.whaa.shop.file.application.ObjectStorageService;import org.apache.tika.Tika;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.ai.document.Document;import org.springframework.ai.vectorstore.VectorStore;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.time.LocalDateTime;import java.util.*;
@Service public class KnowledgeService {private static final Logger log=LoggerFactory.getLogger(KnowledgeService.class);private final KnowledgeFileMapper files;private final ObjectStorageService storage;private final VectorStore vectors;private final Tika tika=new Tika();public KnowledgeService(KnowledgeFileMapper f,ObjectStorageService s,VectorStore v){files=f;storage=s;vectors=v;}
 @Transactional public KnowledgeFile upload(MultipartFile file,long uid){String name=Optional.ofNullable(file.getOriginalFilename()).orElse("knowledge");String lower=name.toLowerCase();if(!(lower.endsWith(".pdf")||lower.endsWith(".docx")||lower.endsWith(".txt")||lower.endsWith(".md")))throw new BusinessException("仅支持 PDF、DOCX、TXT、MD");var stored=storage.upload("knowledge",file);KnowledgeFile k=new KnowledgeFile();k.setFileName(name);k.setObjectKey(stored.objectKey());k.setMimeType(stored.contentType());k.setStatus("PENDING");k.setUploadedBy(uid);k.setCreatedAt(LocalDateTime.now());k.setUpdatedAt(LocalDateTime.now());files.insert(k);index(k.getId());return k;}
 public List<KnowledgeFile> list(){return files.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<KnowledgeFile>().orderByDesc(KnowledgeFile::getCreatedAt));}
 @Async public void index(Long id){KnowledgeFile k=files.selectById(id);if(k==null)return;try(var input=storage.read(k.getObjectKey())){k.setStatus("PROCESSING");files.updateById(k);String text=tika.parseToString(input);if(text==null||text.isBlank())throw new BusinessException("文件中没有可索引文本");vectors.delete("knowledgeFileId == '"+id+"'");List<Document> docs=new ArrayList<>();for(int start=0,part=0;start<text.length();start+=800,part++){String chunk=text.substring(start,Math.min(start+1000,text.length()));docs.add(new Document(chunk,Map.of("knowledgeFileId",String.valueOf(id),"fileName",k.getFileName(),"part",part)));}vectors.add(docs);k.setStatus("READY");k.setErrorMessage(null);}catch(Exception e){log.error("Knowledge indexing failed: id={}, fileName={}",id,k.getFileName(),e);k.setStatus("FAILED");k.setErrorMessage(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage().substring(0,Math.min(900,e.getMessage().length())));}k.setUpdatedAt(LocalDateTime.now());files.updateById(k);}
 public void reindex(Long id){KnowledgeFile k=files.selectById(id);if(k==null)throw new BusinessException("知识文件不存在");k.setStatus("PENDING");k.setErrorMessage(null);files.updateById(k);index(id);}
 @Transactional public void delete(Long id){KnowledgeFile k=files.selectById(id);if(k==null)return;vectors.delete("knowledgeFileId == '"+id+"'");storage.delete(k.getObjectKey());files.deleteById(id);}}
